// WING Remote Protocols 3.1.0, Effects Settings, p.67.
// These are rack algorithms; gate/EQ/compressor channel plugins are separate.
const definitions=[
 ['NONE','Aucun effet','STD','utility'],['EXT','External Insert','STD','route'],
 ['HALL','Hall Reverb','FX1-8','reverb'],['ROOM','Room Reverb','FX1-8','room'],['CHAMBER','Chamber Reverb','FX1-8','room'],['PLATE','Plate Reverb','FX1-8','plate'],['CONCERT','Concert Reverb','FX1-8','reverb'],['AMBI','Ambience','FX1-8','room'],['V-ROOM','Vintage Room','FX1-8','room'],['V-REV','Vintage Reverb','FX1-8','reverb'],['V-PLATE','Vintage Plate','FX1-8','plate'],['GATED','Gated Reverb','FX1-8','gate'],['REVERSE','Reverse Reverb','FX1-8','reverse'],['DEL/REV','Delay / Reverb','FX1-8','delay'],['SHIMMER','Shimmer Reverb','FX1-8','pitch'],['SPRING','Spring Reverb','FX1-8','spring'],['DIMCRS','Dimension CRS','FX1-8','modulation'],['CHORUS','Stereo Chorus','FX1-8','modulation'],['FLANGER','Stereo Flanger','FX1-8','modulation'],['ST-DL','Stereo Delay','FX1-8','delay'],['TAP-DL','Ultratap Delay','FX1-8','delay'],['TAPE-DL','Tape Delay','FX1-8','tape'],['OILCAN','Oilcan Delay','FX1-8','delay'],['BBD-DL','BBD Delay','FX1-8','delay'],['PITCH','Stereo Pitch','FX1-8','pitch'],['D-PITCH','Dual Pitch','FX1-8','pitch'],['VSS3','VSS3 Reverb','FX1-8','reverb'],['BPLATE','Blue Plate Reverb','FX1-8','plate'],
 ['GEQ','Graphic EQ','STD','eq'],['PIA','PIA 560 GEQ','STD','eq'],['DOUBLE','Double Vocal','STD','vocal'],['PCORR','Pitch Fix','STD','pitch'],['LIMITER','Precision Limiter','STD','dynamics'],['DE-S2','De-Esser','STD','dynamics'],['ENHANCE','Stereo Enhancer','STD','enhancer'],['EXCITER','Exciter','STD','enhancer'],['P-BASS','Psycho Bass','STD','bass'],['ROTARY','Rotary Speaker','STD','rotary'],['PHASER','Stereo Phaser','STD','modulation'],['PANNER','Auto Panner','STD','pan'],['TAPE','Tape Machine','STD','tape'],['MOOD','Mood Filter','STD','filter'],['SUB','Sub Octaver','STD','bass'],['RACKAMP','Rack Amplifier','STD','amp'],['UKROCK','UK Rock Amp','STD','amp'],['ANGEL','Angel Amp','STD','amp'],['JAZZC','Jazz Clean Amp','STD','amp'],['DELUXE','Deluxe Amp','STD','amp'],['BODY','BodyRez','STD','guitar'],['SOUL','Soul Analog EQ','STD','eq'],['E88','E88 EQ','STD','eq'],['E84','E84 EQ','STD','eq'],['F110','F110 EQ','STD','eq'],['PULSAR','Pulsar EQ','STD','eq'],['MACH4','Mach4 Multiband','STD','dynamics'],['C5-CMB','C5 Combinator','STD','dynamics'],['SUB-M','Sub Monster','STD','bass'],['V-IMG','Stereo Imager','STD','pan'],['SPKMAN','Speaker Manager','STD','speaker'],['DEQ3','Dynamic EQ','STD','eq'],['*EVEN*','Even Channel','CH','strip'],['*SOUL*','Soul Channel','CH','strip'],['*VINTAGE*','Vintage Channel','CH','strip'],['*BUS*','Bus Channel','CH','strip'],['*MASTER*','Mastering','CH','strip']
];
export const FX_CATALOG=definitions.map(([id,name,group,icon])=>({id,name,group,icon,premium:group==='FX1-8'}));
export const FX_MODELS=Object.fromEntries(FX_CATALOG.map(f=>[f.id,f.name]));
export const effectInfo=id=>FX_CATALOG.find(f=>f.id===id);
export const effectAllowed=(id,slot)=>!!effectInfo(id)&&Number.isInteger(slot)&&slot>=1&&slot<=16&&(!effectInfo(id).premium||slot<=8);
const glyphs={utility:'M5 12h14',route:'M4 7h12l-3-3m3 3-3 3 M20 17H8l3-3m-3 3 3 3',reverb:'M3 18V6h3v12 M10 16V8h3v8 M17 14v-4h3v4',room:'M4 19V5h16v14z M8 15V9h8v6z',plate:'M6 4h12v16H6z M9 8l6 8 M9 12l3 4',gate:'M3 18V6h5v12h5V6h8',reverse:'M3 12h4v-2h4V7h4V4h5 M3 20h17',delay:'M3 6v12 M8 8v8 M13 10v4 M18 11v2 M21 12h1',pitch:'M6 17V6l12-2v11 M6 10l12-2 M6 17c0 3-5 4-5 1s5-4 5-1 M18 15c0 3-5 4-5 1s5-4 5-1',spring:'M2 12h3l2-6 3 12 3-12 3 12 3-6h3',modulation:'M2 12c4-12 6 12 10 0s6 12 10 0 M2 17h20',eq:'M4 4v16 M12 4v16 M20 4v16 M1 8h6 M9 15h6 M17 11h6',vocal:'M5 5a3 3 0 016 0v6a3 3 0 01-6 0z M14 7a3 3 0 016 0v6a3 3 0 01-6 0z M8 17v4 M17 19v2',dynamics:'M3 20 12 7h9 M3 4v16h18',enhancer:'m12 2 2 7 7 3-7 2-2 8-2-8-8-2 8-3z',bass:'M2 12c6-16 14 16 20 0 M3 20h18',rotary:'M12 4a8 8 0 11-8 8 M4 4v8h8 M12 8v8 M8 12h8',pan:'M4 12h16 M4 12l4-4m-4 4 4 4 M20 12l-4-4m4 4-4 4',tape:'M9 8a4 4 0 11-8 0 4 4 0 018 0 M23 8a4 4 0 11-8 0 4 4 0 018 0 M5 12l4 8h6l4-8 M9 16h6',filter:'M2 19c7 0 7-14 12-14s4 14 8 14',amp:'M3 4h18v16H3z M3 8h18 M8 14a4 4 0 118 0 4 4 0 01-8 0',guitar:'M10 8 18 1l4 4-8 7 M10 8c-5-4-11 4-7 8s12-2 7-7 M6 12h1',speaker:'M5 2h14v20H5z M9 6h6 M16 15a4 4 0 11-8 0 4 4 0 018 0',strip:'M4 3v18 M12 3v18 M20 3v18 M1 8h6 M9 12h6 M17 16h6'};
export function effectIcon(id,size=28){const f=effectInfo(id);return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${glyphs[f?.icon]||glyphs.utility}"/></svg>`;}
